function scr_itemget(U1N) {
  if (typeof U1N == "number" && U1N > 0 && U1N < 200) {
    U1N += 200;
  }
  let U1j = 0;
  let U1u = 1;
  this.noroom = 0;
  this._pocketed = 0;
  this._noroominventory = 0;
  (Array.isArray(VF.item) ? VF.item : VF.item = [])[12] = 999;
  for (let U1m = 0; U1u === 1;) {
    if (++U1m > 5000000) {
      throw new Error("GML loop ran 5000000 times without ending");
    }
    if (VF.item[U1j] === 0) {
      (Array.isArray(VF.item) ? VF.item : VF.item = [])[U1j] = U1N;
      break;
    }
    if (U1j === 12) {
      this._noroominventory = 1;
      this.noroom = 1;
      for (let U1d = 0; U1d < VF.flag[64]; U1d++) {
        if (VF.pocketitem[U1d] === 0) {
          nC("debug_message").call(this, "Placed in pocket :" + String(U1d));
          (Array.isArray(VF.pocketitem) ? VF.pocketitem : VF.pocketitem = [])[U1d] = U1N;
          this._pocketed = 1;
          this.noroom = 0;
          break;
        }
      }
      break;
    }
    U1j += 1;
  }
  zY(this, nC("scr_iteminfo_all"));
  nC("debug_message").call(this, "noroom=" + String(this.noroom));
  nC("debug_message").call(this, "_pocketed=" + String(this._pocketed));
  nC("debug_message").call(this, "_noroominventory=" + String(this._noroominventory));
}
bL(scr_itemget, "scr_itemget");
function scr_iteminfo_all() {
  for (this.i = 0; zL(this.i) < 12; this.i += 1) {
    this.itemid = VF.item[this.i];
    nC("scr_iteminfo").call(this, this.itemid);
    (Array.isArray(VF.itemnameb) ? VF.itemnameb : VF.itemnameb = [])[this.i] = this.itemnameb;
    (Array.isArray(VF.itemdescb) ? VF.itemdescb : VF.itemdescb = [])[this.i] = this.itemdescb;
    (Array.isArray(VF.itemvalue) ? VF.itemvalue : VF.itemvalue = [])[this.i] = this.value;
    (Array.isArray(VF.itemusable) ? VF.itemusable : VF.itemusable = [])[this.i] = this.usable;
  }
}
